# Terraform Refactoring: Dev/Prod with for_each

## Current State (Duplicated Blocks)

```hcl
# main.tf (BEFORE - duplicated)
resource "aws_eks_cluster" "dev" {
  name     = "app-dev"
  role_arn = aws_iam_role.eks_cluster_dev.arn
  # ...
}

resource "aws_eks_cluster" "prod" {
  name     = "app-prod"
  role_arn = aws_iam_role.eks_cluster_prod.arn
  # ...
}

resource "aws_s3_bucket" "dev" {
  bucket = "app-assets-dev"
  # ...
}

resource "aws_s3_bucket" "prod" {
  bucket = "app-assets-prod"
  # ...
}

# ... repeated for RDS, IAM, ALB/CloudFront, Secrets
```

## Refactored Solution

### Directory Structure

```
terraform/
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── modules/
│   └── app-infrastructure/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── main.tf
├── variables.tf
├── terraform.tfstate (existing state)
└── moved.tf  # State migration mappings
```

### 1. Root Configuration

```hcl
# main.tf (AFTER - refactored)
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    sops = {
      source  = "carlpett/sops"
      version = "~> 1.0"
    }
  }

  backend "s3" {
    bucket = "terraform-state-bucket"
    key    = "app/terraform.tfstate"
    region = "us-east-1"
  }
}

locals {
  environments = {
    dev = {
      region              = "us-east-1"
      cluster_node_count  = 2
      cluster_node_type   = "t3.medium"
      db_instance_class   = "db.t3.micro"
      db_multi_az         = false
      db_encrypted        = false
      enable_cdn          = false
      enable_replication  = false
      replication_region  = null
      iam_oidc_trust      = false
      acm_certificate_arn = null
    }
    prod = {
      region              = "us-east-1"
      cluster_node_count  = 4
      cluster_node_type   = "t3.large"
      db_instance_class   = "db.t3.medium"
      db_multi_az         = true
      db_encrypted        = true
      enable_cdn          = true
      enable_replication  = true
      replication_region  = "us-west-2"
      iam_oidc_trust      = true
      acm_certificate_arn = "arn:aws:acm:us-east-1:123456789012:certificate/abc123"
    }
  }
}

module "infrastructure" {
  source   = "./modules/app-infrastructure"
  for_each = local.environments

  environment          = each.key
  region               = each.value.region
  cluster_node_count   = each.value.cluster_node_count
  cluster_node_type    = each.value.cluster_node_type
  db_instance_class    = each.value.db_instance_class
  db_multi_az          = each.value.db_multi_az
  db_encrypted         = each.value.db_encrypted
  enable_cdn           = each.value.enable_cdn
  enable_replication   = each.value.enable_replication
  replication_region   = each.value.replication_region
  iam_oidc_trust       = each.value.iam_oidc_trust
  acm_certificate_arn  = each.value.acm_certificate_arn

  providers = {
    aws           = aws
    aws.us-west-2 = aws.us-west-2
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "us-west-2"
  region = "us-west-2"
}
```

### 2. Module Definition

```hcl
# modules/app-infrastructure/variables.tf
variable "environment" {
  type = string
}

variable "region" {
  type = string
}

variable "cluster_node_count" {
  type = number
}

variable "cluster_node_type" {
  type = string
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type = bool
}

variable "db_encrypted" {
  type = bool
}

variable "enable_cdn" {
  type = bool
}

variable "enable_replication" {
  type = bool
}

variable "replication_region" {
  type    = string
  default = null
}

variable "iam_oidc_trust" {
  type = bool
}

variable "acm_certificate_arn" {
  type    = string
  default = null
}
```

```hcl
# modules/app-infrastructure/main.tf

# EKS Cluster
resource "aws_eks_cluster" "main" {
  name     = "app-${var.environment}"
  role_arn = aws_iam_role.eks_cluster.arn
  version  = "1.28"

  vpc_config {
    subnet_ids = data.aws_subnets.private.ids
  }
}

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "app-${var.environment}-nodes"
  node_role_arn   = aws_iam_role.eks_nodes.arn
  subnet_ids      = data.aws_subnets.private.ids
  instance_types  = [var.cluster_node_type]

  scaling_config {
    desired_size = var.cluster_node_count
    max_size     = var.cluster_node_count + 2
    min_size     = var.cluster_node_count
  }
}

# S3 Bucket
resource "aws_s3_bucket" "assets" {
  bucket = "app-assets-${var.environment}"
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket" "assets_replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.us-west-2
  bucket   = "app-assets-${var.environment}-replica"
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.assets_replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [aws_s3_bucket_versioning.assets]
}

# RDS PostgreSQL
resource "aws_db_instance" "main" {
  identifier             = "app-db-${var.environment}"
  engine                 = "postgres"
  engine_version         = "15.4"
  instance_class         = var.db_instance_class
  allocated_storage      = 20
  multi_az               = var.db_multi_az
  storage_encrypted      = var.db_encrypted

  db_name  = "appdb"
  username = "dbadmin"
  password = random_password.db_password.result

  backup_retention_period = 7
  deletion_protection     = true
  publicly_accessible     = false
  skip_final_snapshot     = false
  final_snapshot_identifier = "app-db-${var.environment}-final"
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

# IAM User/Role
resource "aws_iam_user" "app" {
  count = var.iam_oidc_trust ? 0 : 1
  name  = "app-service-${var.environment}"
}

resource "aws_iam_role" "app" {
  name = "app-service-${var.environment}"

  assume_role_policy = var.iam_oidc_trust ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(aws_eks_cluster.main.identity[0].oidc[0].issuer, "https://", "")}"
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${replace(aws_eks_cluster.main.identity[0].oidc[0].issuer, "https://", "")}:sub" = "system:serviceaccount:default:app-service"
        }
      }
    }]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        AWS = aws_iam_user.app[0].arn
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "app" {
  name = "app-service-${var.environment}"
  role = aws_iam_role.app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.assets.arn
      }
    ]
  })
}

# HTTPS Exposure (ALB for dev, CloudFront for prod)
resource "aws_lb" "internal" {
  count              = var.enable_cdn ? 0 : 1
  name               = "app-alb-${var.environment}"
  internal           = true
  load_balancer_type = "application"
  subnets            = data.aws_subnets.private.ids
}

resource "aws_lb_listener" "https" {
  count             = var.enable_cdn ? 0 : 1
  load_balancer_arn = aws_lb.internal[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn   = var.acm_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[0].arn
  }
}

resource "aws_cloudfront_distribution" "main" {
  count   = var.enable_cdn ? 1 : 0
  enabled = true

  origin {
    domain_name = aws_lb.internal[0].dns_name
    origin_id   = "app-origin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "app-origin"
    viewer_protocol_policy = "https-only"

    forwarded_values {
      query_string = true
      cookies {
        forward = "all"
      }
    }
  }

  viewer_certificate {
    acm_certificate_arn = var.acm_certificate_arn
    ssl_support_method  = "sni-only"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

# Secrets (SOPS-encrypted)
data "sops_file" "db_secret" {
  source_file = "${path.module}/secrets/${var.environment}.enc.yaml"
}

resource "kubernetes_secret" "db_connection" {
  metadata {
    name = "db-connection-${var.environment}"
  }

  data = {
    connection_string = "postgresql://${aws_db_instance.main.username}:${random_password.db_password.result}@${aws_db_instance.main.endpoint}/${aws_db_instance.main.db_name}"
  }
}

# Data sources
data "aws_subnets" "private" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.main.id]
  }

  tags = {
    Type = "Private"
  }
}

data "aws_vpc" "main" {
  default = true
}

data "aws_caller_identity" "current" {}
```

### 3. State Migration (Zero-Diff)

```hcl
# moved.tf - Maps existing resources to new module paths
# Run: terraform plan to verify no changes

moved {
  from = aws_eks_cluster.dev
  to   = module.infrastructure["dev"].aws_eks_cluster.main
}

moved {
  from = aws_eks_cluster.prod
  to   = module.infrastructure["prod"].aws_eks_cluster.main
}

moved {
  from = aws_eks_node_group.dev
  to   = module.infrastructure["dev"].aws_eks_node_group.main
}

moved {
  from = aws_eks_node_group.prod
  to   = module.infrastructure["prod"].aws_eks_node_group.main
}

moved {
  from = aws_s3_bucket.dev
  to   = module.infrastructure["dev"].aws_s3_bucket.assets
}

moved {
  from = aws_s3_bucket.prod
