}

moved {
  from = aws_s3_bucket_versioning.dev
  to   = module.infrastructure["dev"].aws_s3_bucket_versioning.assets
}

moved {
  from = aws_s3_bucket_versioning.prod
  to   = module.infrastructure["prod"].aws_s3_bucket_versioning.assets
}

moved {
  from = aws_db_instance.dev
  to   = module.infrastructure["dev"].aws_db_instance.main
}

moved {
  from = aws_db_instance.prod
  to   = module.infrastructure["prod"].aws_db_instance.main
}

moved {
  from = aws_iam_user.dev
